// Posters and validation are generated by default; pass --video to also export MP4.
// Render the font-to-Shape scene with the tmath skill's CPU WASM host.
// Usage: node render-font-shape-rle.mjs /path/to/tmath-skills/assets/wasm [--preview]
// Requires this site's sharp dependency and ffmpeg on PATH. No runtime is shipped.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import sharp from 'sharp';

const dir = path.dirname(fileURLToPath(import.meta.url));
const bundle = path.resolve(process.argv[2]);
const preview = process.argv.includes('--preview');
const temp = path.join(dir, 'temp/font-shape-center-spans');
const output = path.resolve(dir, '../IMAGE/07-SW-Font');
await fs.mkdir(temp, {recursive: true});
await fs.mkdir(output, {recursive: true});
const {createTMath} = await import(pathToFileURL(path.join(bundle, 'client.js')));
const runtime = await createTMath('return tmath.scene {width=1600,height=900,theme="pro_white"}', 'bootstrap.lua', {
  renderEngine: 'cpu', wasmBinary: await fs.readFile(path.join(bundle, 'tmath-wasm.wasm')),
});
runtime.font('Pretendard', await fs.readFile(path.join(bundle, 'Pretendard.ttf')));
const definitions = [
  {name: 'font-shape-rle', file: 'font-shape-rle.lua'},
];
const sheet = [];
const summaries = [];
const boxRight = b => b.x + b.width;
const boxBottom = b => b.y + b.height;
const clearance = (a,b) => Math.min(a.x-b.x, a.y-b.y, boxRight(b)-boxRight(a), boxBottom(b)-boxBottom(a));

try {
  for (const definition of definitions) {
    const source = await fs.readFile(path.join(dir, definition.file), 'utf8');
    runtime.loadLua(source, definition.file);
    const [width, height] = runtime.size();
    const duration = runtime.duration;
    const fps = 30;
    const standalone = new Set([...source.matchAll(/^-- @standalone: (.*)$/gm)].flatMap(m => m[1].split(/\s+/)));
    const standalonePatterns = [...source.matchAll(/^-- @standalone-pattern: (.*)$/gm)]
      .flatMap(m => m[1].split(/\s+/)).map(p => new RegExp(p));
    const containedPatterns = [...source.matchAll(/^-- @contain-pattern: (.*)$/gm)]
      .flatMap(m => m[1].split(/\s+/)).map(entry => {
        const [pattern, target] = entry.split('=');
        const [panel, inset] = target.split(':');
        return {pattern:new RegExp(pattern), panel, inset:Number(inset)};
      });
    const owned = new Map([...source.matchAll(/^-- @contain: (.*)$/gm)].flatMap(m => m[1].split(/\s+/)).map(entry => {
      const [id, target] = entry.split('=');
      const [panel, inset] = target.split(':');
      return [id, {panel, inset: Number(inset)}];
    }));
    const issues = new Set();
    const seen = new Set();
    const intervals = new Map();
    let minCanvas = Infinity, minPanel = Infinity;
    const audit = time => {
      const report = runtime.layoutReport(time, 4);
      const byId = new Map(report.objects.map(o => [o.id, o]));
      const texts = report.objects.filter(o => o.type === 'text' && o.visible);
      // The moving end tick must stay on the length line, whose origin is the
      // CENTER of the start-pixel mark (the Overview's spanGlyph convention).
      for (const mark of report.objects) {
        const match=mark.id?.match(/^span_begin_(\d+)$/);
        if (!match || !mark.visible) continue;
        const shaft=byId.get(`span_length_${match[1]}`);
        const end=byId.get(`span_end_${match[1]}`);
        if (!shaft?.visible || !end?.visible) continue;
        const a=mark.paintBounds,b=shaft.paintBounds,c=end.paintBounds;
        if (!a || !b || !c) {issues.add(`span null bounds: ${match[1]}`);continue;}
        const bx=a.x+a.width/2,by=a.y+a.height/2;
        if (Math.abs(b.x+b.height/2-bx)>0.05 || Math.abs(b.y+b.height/2-by)>0.05 ||
            Math.abs(boxRight(b)-b.height/2-(c.x+c.width/2))>0.05 ||
            Math.abs(c.y+c.height/2-by)>0.05) issues.add(`span center/end alignment: ${match[1]}`);
      }
      for (const t of texts) {
        // Expand explicit, anchored ID-family rules into a complete ownership ledger.
        for (const rule of containedPatterns) if (rule.pattern.test(t.id)) {
          owned.set(t.id, {panel:t.id.replace(rule.pattern,rule.panel), inset:rule.inset});
        }
        if (standalonePatterns.some(p => p.test(t.id))) standalone.add(t.id);
        seen.add(t.id);
        const interval=intervals.get(t.id) || {first:time,last:time};
        interval.last=time; intervals.set(t.id,interval);
        const b = t.paintBounds;
        if (!b || b.width <= 0 || b.height <= 0) { issues.add(`null bounds: ${t.id}`); continue; }
        const c = clearance(b, {x:0, y:0, width, height});
        minCanvas = Math.min(c, minCanvas);
        if (c < 4) issues.add(`canvas: ${t.id} @ ${time}`);
        if (owned.has(t.id)) {
          const {panel, inset} = owned.get(t.id);
          const bound = byId.get(panel)?.paintBounds;
          if (!bound) { issues.add(`missing panel: ${panel}`); continue; }
          const c = clearance(b, bound);
          minPanel = Math.min(minPanel, c);
          if (c < inset) issues.add(`containment: ${t.id} in ${panel}: ${c.toFixed(2)}`);
        } else if (!standalone.has(t.id)) issues.add(`missing ledger: ${t.id}`);
      }
      for (let i=0; i<texts.length; i++) for (let j=i+1; j<texts.length; j++) {
        const a=texts[i].paintBounds, b=texts[j].paintBounds;
        if (!a || !b) continue;
        const dx=Math.max(b.x-boxRight(a), a.x-boxRight(b));
        const dy=Math.max(b.y-boxBottom(a), a.y-boxBottom(b));
        if (dx < 4 && dy < 4) issues.add(`text gap: ${texts[i].id} / ${texts[j].id}`);
      }
      return report;
    };
    const times = Array.from({length: Math.ceil(duration*fps)+1}, (_,i) => Math.min(i/fps,duration));
    for (const time of times) audit(time);
    const finalObjects=runtime.layoutReport(duration,4).objects;
    const finalById=new Map(finalObjects.map(o=>[o.id,o]));
    const unit=finalById.get('grid_x_1').paintBounds.x-finalById.get('grid_x_0').paintBounds.x;
    const spanLengths=new Map();
    for (const o of finalObjects) {
      const match=o.id?.match(/^record_(\d+)_data_(\d+)$/);
      if (match) spanLengths.set(match[1],Math.max(spanLengths.get(match[1])||0,Number(match[2])));
    }
    for (const [id,len] of spanLengths) {
      const shaft=finalById.get(`span_length_${id}`);
      if (!shaft?.visible || Math.abs(shaft.paintBounds.width-shaft.paintBounds.height-len*unit)>0.05)
        issues.add(`final span length/persistence: ${id}`);
    }
    for (const id of [...standalone, ...owned.keys()]) if (!seen.has(id)) issues.add(`unused ledger: ${id}`);
    const summary = {name:definition.name, duration, width, height, fps, framesAudited:times.length,
      minCanvasClearance:minCanvas, minPanelClearance:Number.isFinite(minPanel)?minPanel:null,
      spansGeometryVerified:spanLengths.size, issues:[...issues]};
    summaries.push(summary);
    console.log(JSON.stringify({...summary,issueCount:issues.size,issues:summary.issues.slice(0,20)}));
    await fs.writeFile(path.join(temp,'text-state-intervals.json'),JSON.stringify(Object.fromEntries(intervals),null,2));
    await fs.writeFile(path.join(temp, definition.name+(preview?'-preview':'')+'-audit.json'),JSON.stringify(summary,null,2));
    if (issues.size) throw new Error(`${definition.name}: layout audit failed`);
    await fs.writeFile(path.join(temp,'text-ownership.json'),JSON.stringify({
      standalone:[...standalone],contained:Object.fromEntries(owned),
    },null,2));
    const middle = id => {
      const interval=intervals.get(id);
      if (!interval) throw Error(`Missing decisive state: ${id}`);
      return (interval.first+interval.last)/2;
    };
    const samples = [0,middle('cubic_note'),middle('probe_1_2'),middle('probe_4_6'),middle('probe_10_8'),duration];

    for (const time of samples) {
      const pixels=runtime.render(time,true);
      await sharp(Buffer.from(pixels),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,`${definition.name}-${time.toFixed(2)}.png`));
    }
    for (const time of samples) {
      sheet.push(await sharp(Buffer.from(runtime.render(time,true)),{raw:{width,height,channels:4}}).resize(800,450).jpeg({quality:78}).toBuffer());
    }
    await sharp(Buffer.from(runtime.render(duration,true)),{raw:{width,height,channels:4}}).webp({quality:88}).toFile(path.join(output,definition.name+'.webp'));
    // Subpixel placement must affect geometry, numeric coverage AND stored data.
    const before = runtime.bounds('reference_1', duration);
    const crop = async (time, left, top, w, h) => sharp(Buffer.from(runtime.render(time,true)),
      {raw:{width,height,channels:4}}).extract({left,top,width:w,height:h}).raw().toBuffer();
    const numbersBefore = await crop(middle('probe_10_1'),80,767,850,46);
    const recordBefore = await crop(duration,820,326,690,368);
    runtime.loadLua(source.replace('local xOffset=1.1','local xOffset=1.2'), 'subpixel-variant.lua');
    const after = runtime.bounds('reference_1', runtime.duration);
    if (Math.abs(after.x-before.x-2.6)>0.05 || Math.abs(after.width-before.width)>0.05) throw Error('Glyph placement dependency failed');
    let variantRowTime;
    for (let time=0;time<runtime.duration;time+=1/fps) {
      if (runtime.layoutReport(time,4).objects.some(o=>o.id==='probe_10_1' && o.visible)) {variantRowTime=time+0.08;break;}
    }
    if (variantRowTime===undefined) throw Error('Variant scan never reached row 10');
    if (numbersBefore.equals(await crop(variantRowTime,80,767,850,46))) throw Error('Numeric coverage did not follow placement');
    if (recordBefore.equals(await crop(runtime.duration,820,326,690,368))) throw Error('Stored span did not follow coverage');
    runtime.loadLua(source,definition.file);
    console.log('PASS: subpixel placement changes glyph position, numeric coverage and stored span');
    if (preview || !process.argv.includes('--video')) continue;

    const ffmpeg=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba',
      '-video_size',`${width}x${height}`,'-framerate',String(fps),'-i','pipe:0','-an','-c:v','libx264','-preset','medium',
      '-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(output,definition.name+'.mp4')],{stdio:['pipe','inherit','inherit']});
    const completed=once(ffmpeg,'close');
    ffmpeg.stdin.on('error', error => console.error(error.message));
    const frames=Math.ceil(duration*fps)+1; // include the exact final state
    for (let frame=0;frame<frames;frame++) {
      const pixels=Buffer.from(runtime.render(Math.min(frame/fps,duration),true));
      if (!ffmpeg.stdin.write(pixels)) await once(ffmpeg.stdin,'drain');
      if (frame%150===0) console.log(`${definition.name}: ${frame}/${frames}`);
    }
    ffmpeg.stdin.end();
    const [code]=await completed;
    if (code!==0) throw new Error(`ffmpeg exited ${code}`);
  }
  // One bounded contact sheet for the six semantic beats.
  await sharp({create:{width:1600,height:1350,channels:3,background:'#ffffff'}}).composite(
    sheet.map((input,i)=>({input,left:(i%2)*800,top:Math.floor(i/2)*450})),
  ).jpeg({quality:80}).toFile(path.join(temp,preview?'preview-sheet.jpg':'final-sheet.jpg'));
  await fs.writeFile(path.join(temp,preview?'preview-audit-summary.json':'audit-summary.json'),JSON.stringify(summaries,null,2));
} finally {
  runtime.destroy();
}
